  ('learn-sandpit-river-erosion', 'Sandpit river erosion', 'Build a sand hill in a tray or sandpit and pour water slowly from the top. Watch channels, deltas and meanders appear and try adding pebbles as hard rock.', 'learn', null, 25, 'easy', 'outdoors', 'high', 'free', 'either', 10, false, false, null, 'erosion experiment sand tray', 'published', 'seed', now()),
