  ('music-pentatonic-box-one', 'Pentatonic box one', 'Learn the first box shape of the minor pentatonic scale, then improvise over a backing track using only those notes. Nothing you play can sound wrong.', 'music', null, 30, 'medium', 'computer', 'medium', 'free', 'alone', 20, false, false, null, 'minor pentatonic scale box 1 guitar', 'published', 'seed', now()),
