  ('physical-open-water-swim-session', 'Open water swim session', 'Join a supervised open water swim at a lake with lifeguards. Wear a bright cap and stay close to the shore.', 'physical', null, 60, 'hard', 'outdoors', 'high', 'paid', 'either', 35, false, false, 'Only swim at supervised venues and never alone.', null, 'published', 'seed', now()),
  ('physical-sea-dip-with-friends', 'Sea dip with friends', 'On a calm day at a lifeguarded beach, wade in with friends for a short swim close to shore. Bring warm layers and a hot drink for after.', 'physical', null, 40, 'medium', 'outdoors', 'medium', 'free', 'with_friends', 20, false, false, 'Only at lifeguarded beaches, never alone, and get out before you get cold.', null, 'published', 'seed', now()),
  ('physical-aqua-jogging', 'Aqua jogging', 'In the deep end with a float belt, run in the water without touching the bottom for twenty minutes. Zero impact, plenty of effort.', 'physical', null, 30, 'medium', 'indoors', 'high', 'paid', 'alone', 20, false, false, 'Use a float belt and stay near the side.', null, 'published', 'seed', now()),
  ('physical-learn-to-tread-water', 'Learn to tread water', 'In water where you can stand, practise eggbeater or scissor kicks while sculling with your hands. Build up to a minute.', 'physical', null, 20, 'medium', 'indoors', 'medium', 'paid', 'alone', 20, false, false, 'Practise near the side with a lifeguard on duty.', 'how to tread water', 'published', 'seed', now()),
  ('physical-pool-interval-sets', 'Pool interval sets', 'Swim four sets of two fast lengths with thirty seconds of rest between, then two easy ones. Watch the pace clock.', 'physical', null, 35, 'hard', 'indoors', 'high', 'paid', 'alone', 35, false, false, 'Stop if you feel dizzy or short of breath.', null, 'published', 'seed', now()),
  ('physical-swim-a-mile', 'Swim a mile', 'Work out how many lengths make a mile in your pool and swim them all, stopping as often as you like.', 'physical', null, 70, 'insane', 'indoors', 'high', 'paid', 'alone', 50, false, false, 'Rest at the wall whenever you need to.', null, 'published', 'seed', now()),
