  ('physical-shoulder-dislocates-with-a-towel', 'Shoulder dislocates with a towel', 'Hold a long towel wide with both hands and lift it slowly over your head and behind you, then back. Ten reps, widening your grip if it pinches.', 'physical', null, 4, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, 'Keep your grip wide enough that it never hurts.', 'towel shoulder dislocates', 'published', 'seed', now()),
  ('physical-wall-angels', 'Wall angels', 'Stand with your back flat against a wall and slide your arms up and down like a snow angel, keeping your elbows and wrists touching it.', 'physical', null, 4, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'wall angels exercise', 'published', 'seed', now()),
  ('physical-touch-your-toes-project', 'Touch your toes project', 'Test whether you can touch your toes, then do five minutes of hamstring stretches every day this week and test again on Sunday.', 'physical', null, 6, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-front-splits-progress', 'Front splits progress', 'Practise low lunges and half splits towards the front splits, holding each for forty-five seconds. Measure the gap to the floor with a ruler.', 'physical', null, 15, 'hard', 'indoors', 'low', 'free', 'alone', 35, false, false, 'Never bounce and stop at a gentle stretch.', 'front splits stretching routine for beginners', 'published', 'seed', now()),
  ('physical-middle-splits-routine', 'Middle splits routine', 'Stretch your inner thighs with wide-leg folds, frog stretch and side lunges, holding each for a minute.', 'physical', null, 15, 'hard', 'indoors', 'low', 'free', 'alone', 35, false, false, 'Go gently and never force the range.', 'middle splits stretching routine', 'published', 'seed', now()),
  ('physical-bridge-pose-progress', 'Bridge pose progress', 'From lying on your back, push up into a full back bridge, or practise the half version with shoulders on the floor. Five holds of ten seconds.', 'physical', null, 10, 'hard', 'indoors', 'medium', 'free', 'alone', 35, false, false, 'Warm up first and skip it if you have back problems.', 'how to do a bridge backbend for beginners', 'published', 'seed', now()),
  ('physical-neck-release-sequence', 'Neck release sequence', 'Slowly tilt your ear to each shoulder, look over each shoulder and nod gently, holding each for twenty seconds.', 'physical', null, 3, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, 'Move slowly and never roll your neck hard.', null, 'published', 'seed', now()),
  ('physical-wrist-warm-up', 'Wrist warm-up', 'Circle your wrists, then on hands and knees rock gently over your palms facing forward, sideways and back. Essential before push-ups.', 'physical', null, 4, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, 'wrist warm up routine', 'published', 'seed', now()),
  ('physical-full-body-mobility-flow', 'Full-body mobility flow', 'Link together arm circles, hip circles, cat-cow, deep squat and spinal twists into a slow flow that lasts fifteen minutes.', 'physical', null, 15, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, '15 minute full body mobility routine', 'published', 'seed', now()),
  ('physical-couch-stretch', 'Couch stretch', 'Kneel with one knee against the bottom of the sofa and foot up its back, then lift your chest tall. Two minutes each side opens tight hips.', 'physical', null, 5, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, 'Pad your knee and ease in slowly.', 'couch stretch hip flexor', 'published', 'seed', now()),
  ('physical-pigeon-stretch', 'Pigeon stretch', 'Fold one leg in front of you and stretch the other behind, sinking your hips down. Hold for a minute each side and breathe.', 'physical', null, 4, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, 'Support your hip with a cushion if your knee complains.', null, 'published', 'seed', now()),
  ('physical-hip-flexor-lunge-stretch', 'Hip flexor lunge stretch', 'Kneel in a lunge and gently push your hips forward until you feel a stretch in the front of your back leg. Squeeze that glute and hold.', 'physical', null, 3, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-joint-by-joint-warm-up', 'Joint-by-joint warm-up', 'Start at your neck and move every joint in turn down to your ankles: circles, nods, rolls and swings. Ten of each.', 'physical', null, 8, 'easy', 'anywhere', 'medium', 'free', 'either', 10, false, false, null, 'joint mobility warm up routine', 'published', 'seed', now()),
  ('physical-partner-stretch-session', 'Partner stretch session', 'With a friend, take turns gently assisting hamstring, shoulder and back stretches. Communicate constantly and stop at the first sign of discomfort.', 'physical', null, 20, 'easy', 'indoors', 'low', 'free', 'with_friends', 10, false, false, 'The stretched person controls how far you go.', 'partner stretching routine', 'published', 'seed', now()),
  ('physical-flexibility-test-before-and-after', 'Flexibility test before and after', 'Measure how far you reach in a seated toe touch, then stretch for ten minutes and measure again. Note the difference.', 'physical', null, 15, 'easy', 'indoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-desk-posture-reset', 'Desk posture reset', 'Set a timer for every thirty minutes today. Each time it goes off, stand, roll your shoulders back, tuck your chin and take three deep breaths.', 'physical', null, 2, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-chin-tucks', 'Chin tucks', 'Sit tall and slide your head straight back to make a double chin, hold for three seconds and release. Ten reps undo hours of phone neck.', 'physical', null, 2, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, 'chin tuck exercise', 'published', 'seed', now()),
  ('physical-posture-photo-check', 'Posture photo check', 'Have a friend take a side-on photo of you standing naturally, then look for forward head or rounded shoulders and practise standing tall.', 'physical', null, 8, 'easy', 'indoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-back-against-the-wall-test', 'Back against the wall test', 'Stand with heels, bottom, shoulders and head touching a wall and hold for a minute. Then walk away trying to keep that shape.', 'physical', null, 3, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-band-pull-aparts', 'Band pull-aparts', 'Hold a resistance band at shoulder height and pull it apart, squeezing your shoulder blades. Three sets of fifteen for better posture.', 'physical', null, 5, 'easy', 'anywhere', 'medium', 'paid', 'alone', 10, false, false, null, 'band pull aparts posture', 'published', 'seed', now()),
  ('physical-prone-y-t-w-raises', 'Prone Y-T-W raises', 'Lie face down and lift your arms into a Y, then a T, then a W shape, holding each for three seconds. Ten rounds.', 'physical', null, 6, 'medium', 'indoors', 'medium', 'free', 'alone', 20, false, false, null, 'ytw exercise posture', 'published', 'seed', now()),
  ('physical-standing-desk-hour', 'Standing desk hour', 'Work standing up for an hour today, propping your laptop on a stack of books at elbow height. Shift your weight often.', 'physical', null, 60, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-posture-perfect-walk', 'Posture-perfect walk', 'Go for a walk focusing only on posture: tall crown, relaxed shoulders, swinging arms, soft knees. Check in every lamppost.', 'physical', null, 20, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-phone-at-eye-level-day', 'Phone-at-eye-level day', 'For the rest of the day, lift your phone to eye level whenever you use it instead of looking down. Count how often you catch yourself.', 'physical', null, 120, 'easy', 'anywhere', 'low', 'free', 'alone', 15, true, false, null, null, 'published', 'seed', now()),
  ('physical-doorway-chest-stretch', 'Doorway chest stretch', 'Place your forearms on a door frame and step through gently until you feel your chest open. Hold for thirty seconds three times.', 'physical', null, 3, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-scapular-push-ups', 'Scapular push-ups', 'In a plank, keep your arms straight and let your chest sink between your shoulder blades, then push it away. Fifteen slow reps.', 'physical', null, 4, 'easy', 'anywhere', 'medium', 'free', 'alone', 10, false, false, null, 'scapular push ups', 'published', 'seed', now()),
  ('physical-hip-hinge-broomstick-drill', 'Hip hinge broomstick drill', 'Hold a broom along your spine touching your head, upper back and tailbone, then practise hinging forward without losing contact.', 'physical', null, 6, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'hip hinge dowel drill', 'published', 'seed', now()),
  ('physical-shoulder-blade-squeeze-breaks', 'Shoulder blade squeeze breaks', 'Every hour, squeeze your shoulder blades together and down for five seconds, ten times. Set a reminder so you do not forget.', 'physical', null, 2, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-morning-stretch-in-bed', 'Morning stretch in bed', 'Before getting up, stretch arms overhead, hug knees to chest, twist each way and point and flex your toes. Five minutes and up.', 'physical', null, 5, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-bedtime-wind-down-stretch', 'Bedtime wind-down stretch', 'Ten minutes before sleep, do slow forward folds, child''s pose, a lying twist and legs up the wall. Lights low, phone away.', 'physical', null, 10, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-post-run-stretch-routine', 'Post-run stretch routine', 'After any run or walk, stretch calves, quads, hamstrings and hips for thirty seconds each per side. Do it while you are still warm.', 'physical', null, 10, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, 'post run stretching routine', 'published', 'seed', now()),
  ('physical-hamstring-strap-stretch', 'Hamstring strap stretch', 'Lie on your back and loop a towel around one foot, lifting the straight leg until you feel the stretch. Hold for a minute each side.', 'physical', null, 5, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-office-chair-stretch-set', 'Office chair stretch set', 'Without leaving your chair, stretch your neck, wrists, spine twist, figure-four hips and ankle circles. Nobody will notice.', 'physical', null, 5, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('physical-calf-stretch-on-a-step', 'Calf stretch on a step', 'Let your heels drop off the edge of a step and hold for thirty seconds, then bend your knees slightly and hold again.', 'physical', null, 3, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, 'Hold the rail.', null, 'published', 'seed', now()),
  ('physical-thirty-day-flexibility-challenge', 'Thirty-day flexibility challenge', 'Commit to ten minutes of stretching every day for a month, rotating hips, hamstrings and shoulders. Do day one now.', 'physical', null, 10, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
