  ('productivity-habit-tracker-app-setup', 'Habit tracker app setup', 'Install a habit tracking app, add no more than three habits, and set one reminder each at the time you are most likely to do them.', 'productivity', null, 10, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
