  ('productivity-environment-design-sweep', 'Environment design sweep', 'Walk through your home and change three things to make a good habit easier, such as leaving a book on your pillow or a water bottle on your desk.', 'productivity', null, 15, 'easy', 'indoors', 'high', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
