  ('productivity-deep-work-block', 'Deep work block', 'Close email and chat, put your phone in another room and work on one hard task for ninety minutes. Write what you got done at the end.', 'productivity', null, 90, 'hard', 'computer', 'medium', 'free', 'alone', 35, false, false, null, 'deep work Cal Newport summary', 'published', 'seed', now()),
