  ('productivity-brain-dump', 'Brain dump', 'Set a ten-minute timer and write every single thing on your mind, from big worries to buy batteries. Then circle the three that actually need doing this week.', 'productivity', null, 10, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
