  ('productivity-focus-soundtrack-test', 'Focus soundtrack test', 'Try three kinds of focus audio, such as brown noise, lo-fi and film scores, for ten minutes each while working. Keep the one that made time disappear.', 'productivity', null, 30, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('productivity-timeboxed-sprint-race', 'Timeboxed sprint race', 'Write five small tasks on cards, set a twenty-minute timer and race to finish them all. Flip each card over as you go and do a victory lap of the room if you win.', 'productivity', null, 20, 'easy', 'indoors', 'high', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
