  ('learn-music-accidentals-that-outlast-the-note', 'Accidentals that outlast the note', 'Learn the rule that a sharp or flat lasts until the end of the bar. Spot every accidental in a page of music and work out which later notes they change.', 'learn', 'music', 15, 'medium', 'anywhere', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-ear-train-with-a-drone', 'Ear-train with a drone', 'Play a drone note from an app and sing each degree of the major scale against it, holding until it stops wobbling. Learn how in-tune notes lock into place.', 'learn', 'music', 15, 'medium', 'anywhere', 'low', 'free', 'alone', 20, false, false, null, 'drone ear training singing', 'published', 'seed', now()),
  ('learn-music-melodic-dictation-from-a-jingle', 'Melodic dictation from a jingle', 'Pick a short advert jingle and try to write its melody down using note names. Check it on a keyboard app and fix every wrong note.', 'learn', 'music', 25, 'hard', 'anywhere', 'low', 'free', 'alone', 35, false, false, null, 'melodic dictation tips', 'published', 'seed', now()),
  ('learn-music-rhythm-dictation-duel', 'Rhythm dictation duel', 'One person claps a two-bar rhythm and the other writes it down in notation. Swap roles and see who can catch the trickiest syncopation.', 'learn', 'music', 15, 'medium', 'anywhere', 'medium', 'free', 'with_friends', 20, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-chord-quality-quiz-party', 'Chord quality quiz party', 'Take turns playing chords on a keyboard while everyone else shouts major, minor, diminished or augmented. Keep score and crown the sharpest ear.', 'learn', 'music', 20, 'medium', 'indoors', 'medium', 'free', 'with_friends', 20, false, false, null, 'chord quality ear training', 'published', 'seed', now()),
  ('learn-music-perfect-pitch-myth-check', 'Perfect pitch myth check', 'Read up on what perfect pitch is and how rare it is, then test your pitch memory by humming a favourite song''s first note and checking it with a tuner app.', 'learn', 'music', 10, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-relative-pitch-reference-note', 'Relative pitch reference note', 'Learn to remember an A at 440 hertz by humming it every morning for a week. Test yourself each day before checking with a tuner.', 'learn', 'music', 5, 'medium', 'anywhere', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-learn-the-diminished-chord-shiver', 'Learn the diminished chord shiver', 'Stack minor thirds on any note to build a diminished chord and hear why it was used in silent films for villains. Play three in a row up the keyboard for maximum drama.', 'learn', 'music', 10, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'diminished chord explained', 'published', 'seed', now()),
  ('learn-music-augmented-chord-dream-sequence', 'Augmented chord dream sequence', 'Learn to build an augmented chord by stacking two major thirds. Play it and notice why films use it for dreamy flashbacks and confusion.', 'learn', 'music', 10, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'augmented chord explained', 'published', 'seed', now()),
  ('learn-music-chord-tones-over-a-backing-track', 'Chord tones over a backing track', 'Pick a simple two-chord backing track and improvise using only the notes of whichever chord is playing. Learn how solos stay melodic by landing on chord tones.', 'learn', 'music', 20, 'hard', 'indoors', 'medium', 'free', 'alone', 35, false, false, null, 'target chord tones improvisation', 'published', 'seed', now()),
  ('learn-music-blues-scale-six-notes', 'Blues scale six notes', 'Learn the six-note blues scale with its flat fifth, then play it slowly over a twelve-bar blues backing track. Bend or slide into the blue note for extra feeling.', 'learn', 'music', 20, 'medium', 'indoors', 'medium', 'free', 'alone', 20, false, false, null, 'blues scale for beginners', 'published', 'seed', now()),
  ('learn-music-learn-the-twelve-bar-on-any-instrument', 'Learn the twelve-bar on any instrument', 'Write out the twelve-bar blues chord pattern in numerals and play it on whatever you have, even a keyboard app. Sing a made-up blues lyric over it.', 'learn', 'music', 25, 'medium', 'anywhere', 'medium', 'free', 'either', 20, false, false, null, '12 bar blues explained', 'published', 'seed', now()),
  ('learn-music-name-the-scale-degrees', 'Name the scale degrees', 'Learn the formal names tonic, supertonic, mediant, subdominant, dominant, submediant and leading note. Point to each on a keyboard while saying it out loud.', 'learn', 'music', 10, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-harmonic-minor-exotic-step', 'Harmonic minor exotic step', 'Learn how raising the seventh of a minor scale creates the harmonic minor with its dramatic gap. Play it up and down and spot it in a film score.', 'learn', 'music', 15, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'harmonic minor scale explained', 'published', 'seed', now()),
  ('learn-music-melodic-minor-two-faced-scale', 'Melodic minor two-faced scale', 'Learn the melodic minor that goes up one way and comes down another. Play it slowly five times and say why classical composers liked it.', 'learn', 'music', 15, 'hard', 'indoors', 'low', 'free', 'alone', 35, false, false, null, 'melodic minor scale explained', 'published', 'seed', now()),
  ('learn-music-whole-tone-scale-wobble', 'Whole tone scale wobble', 'Learn the whole tone scale, made of nothing but equal steps, and hear why it sounds like a dream starting. Play it on a keyboard and improvise a spooky intro.', 'learn', 'music', 10, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'whole tone scale explained', 'published', 'seed', now()),
  ('learn-music-chromatic-scale-fingering', 'Chromatic scale fingering', 'Learn the standard piano fingering for the chromatic scale, using thumb on white keys and third finger on black. Play it two octaves without a stumble.', 'learn', 'music', 15, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'chromatic scale piano fingering', 'published', 'seed', now()),
  ('learn-music-locrian-the-unloved-mode', 'Locrian, the unloved mode', 'Learn why the Locrian mode, B to B on white keys, is so rarely used: its home chord is diminished and never settles. Try writing a four-bar tune in it and see if you can make it feel like home.', 'learn', 'music', 20, 'hard', 'indoors', 'low', 'free', 'alone', 35, false, false, null, 'locrian mode explained', 'published', 'seed', now()),
  ('learn-music-secondary-dominant-spice', 'Secondary dominant spice', 'Learn how to borrow the dominant of a chord that is not the home chord, like D7 before G in the key of C. Add one to a simple progression and hear the lift.', 'learn', 'music', 25, 'hard', 'indoors', 'low', 'free', 'alone', 35, false, false, null, 'secondary dominants explained', 'published', 'seed', now()),
  ('learn-music-borrowed-chord-sadness', 'Borrowed chord sadness', 'Learn how pop songs borrow the minor iv chord from the parallel minor. Play C, F, F minor, C and hear the bittersweet twist.', 'learn', 'music', 15, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'minor iv chord borrowed chord', 'published', 'seed', now()),
  ('learn-music-the-four-chord-pop-discovery', 'The four-chord pop discovery', 'Learn the I, V, vi, IV progression and play it while a friend sings as many hit songs over it as they can. Count how many fit.', 'learn', 'music', 20, 'easy', 'indoors', 'medium', 'free', 'with_friends', 10, false, false, null, 'four chord song progression', 'published', 'seed', now()),
  ('learn-music-circle-progression-chain', 'Circle progression chain', 'Learn how chords moving down by fifths, like E minor, A minor, D minor, G, C, create an unstoppable sense of travel. Play it and find it in a jazz standard.', 'learn', 'music', 25, 'hard', 'indoors', 'low', 'free', 'alone', 35, false, false, null, 'circle of fifths progression', 'published', 'seed', now()),
  ('learn-music-tritone-substitution-secret', 'Tritone substitution secret', 'Learn the jazz trick of swapping a dominant chord for the one a tritone away. Play both versions of a ii, V, I and listen for the sliding bass.', 'learn', 'music', 30, 'insane', 'indoors', 'low', 'free', 'alone', 50, false, false, null, 'tritone substitution explained', 'published', 'seed', now()),
  ('learn-music-polyrhythm-3-over-4-phrase', 'Polyrhythm 3 over 4 phrase', 'Learn the saying pass the golden butter to lock in a three against four polyrhythm. Tap it on your knees until both hands keep going without you thinking.', 'learn', 'music', 10, 'hard', 'anywhere', 'medium', 'free', 'alone', 35, false, false, null, '3 over 4 polyrhythm', 'published', 'seed', now()),
  ('learn-music-swing-feel-versus-straight', 'Swing feel versus straight', 'Learn the difference between straight and swung quavers by speaking the rhythm doo-ba doo-ba. Play a tune both ways and decide which suits it.', 'learn', 'music', 10, 'easy', 'anywhere', 'medium', 'free', 'alone', 10, false, false, null, 'swing rhythm explained', 'published', 'seed', now()),
  ('learn-music-syncopation-stomp', 'Syncopation stomp', 'Learn what syncopation is by stamping on the off-beats while counting one-and-two-and. Stomp along to a funk track and try not to drift onto the beat.', 'learn', 'music', 10, 'medium', 'indoors', 'high', 'free', 'either', 20, false, false, null, 'syncopation explained', 'published', 'seed', now()),
  ('learn-music-hemiola-hunting', 'Hemiola hunting', 'Learn how a hemiola makes three bars of two feel like two bars of three. Find one in a baroque minuet and clap through it with a friend.', 'learn', 'music', 20, 'hard', 'anywhere', 'low', 'free', 'either', 35, false, false, null, 'hemiola explained', 'published', 'seed', now()),
  ('learn-music-tuplet-triplet-clap', 'Tuplet triplet clap', 'Learn to clap crotchet triplets against a steady metronome, fitting three even claps into two beats. Start slow and speed up by five beats per minute each round.', 'learn', 'music', 10, 'hard', 'anywhere', 'medium', 'free', 'alone', 35, false, false, null, 'quarter note triplets', 'published', 'seed', now()),
  ('learn-music-metronome-on-two-and-four', 'Metronome on two and four', 'Set a metronome slow and treat each click as beats two and four. Learn why jazz players practise this to build a stronger groove.', 'learn', 'music', 10, 'medium', 'anywhere', 'medium', 'free', 'alone', 20, false, false, null, 'metronome on 2 and 4', 'published', 'seed', now()),
  ('learn-music-count-rests-out-loud', 'Count rests out loud', 'Learn to survive long rests by counting the bars on your fingers while a recording plays. Come in at exactly the right moment on a piece with a sixteen-bar gap.', 'learn', 'music', 10, 'medium', 'anywhere', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-learn-the-harmonic-series-by-ear', 'Learn the harmonic series by ear', 'Learn that every note contains hidden higher notes. Sing a low note into a resonant room and try to hear the octave, fifth and third shimmering above it.', 'learn', 'music', 10, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'harmonic series explained overtones', 'published', 'seed', now()),
  ('learn-music-overtone-singing-first-sound', 'Overtone singing first sound', 'Learn to sing two notes at once by shaping your mouth from oo to ee on a single held pitch. Keep going until you hear a faint whistle floating above your voice.', 'learn', 'music', 15, 'hard', 'anywhere', 'low', 'free', 'alone', 35, false, false, null, 'overtone singing tutorial for beginners', 'published', 'seed', now()),
  ('learn-music-equal-temperament-explained', 'Equal temperament explained', 'Learn why a piano is slightly out of tune on purpose so every key works. Compare a pure fifth from a drone app with a piano fifth and listen for the gentle beating.', 'learn', 'music', 20, 'hard', 'computer', 'low', 'free', 'alone', 35, false, false, null, 'equal temperament explained', 'published', 'seed', now()),
  ('learn-music-learn-what-a-hertz-is', 'Learn what a hertz is', 'Use a tone generator app to play 100, 440 and 1000 hertz. Learn how frequency becomes pitch and find the highest tone you can still hear.', 'learn', 'music', 10, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, 'keep the volume low when testing high tones', null, 'published', 'seed', now()),
  ('learn-music-beating-tones-experiment', 'Beating tones experiment', 'Play two tone generators at 440 and 443 hertz at the same time. Learn why you hear a slow wobble and use it to tune by ear the old-fashioned way.', 'learn', 'music', 10, 'medium', 'computer', 'low', 'free', 'alone', 20, false, false, 'keep the volume low', null, 'published', 'seed', now()),
  ('learn-music-decibel-diary', 'Decibel diary', 'Use a sound meter app to measure your kettle, a busy road, your voice and your favourite song through headphones. Learn which levels can harm hearing over time.', 'learn', 'music', 15, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('learn-music-why-a-guitar-string-sings', 'Why a guitar string sings', 'Pluck a string and press it at the twelfth fret to halve its length. Learn the link between string length and pitch and predict the note before you play.', 'learn', 'music', 10, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'physics of guitar strings', 'published', 'seed', now()),
  ('learn-music-bottle-organ-physics', 'Bottle organ physics', 'Fill eight glass bottles with different water levels and tune them to a scale by blowing across the tops. Learn why less air makes a higher note.', 'learn', 'music', 30, 'medium', 'indoors', 'medium', 'free', 'either', 20, false, false, 'use sturdy bottles on a towel', 'how to tune bottles to a scale', 'published', 'seed', now()),
  ('learn-music-cupped-hand-owl-call', 'Cupped-hand owl call', 'Learn to make a hooting owl sound by cupping your hands into a hollow chamber and blowing across the gap between your thumbs. Change the pitch by lifting your fingers like an ocarina.', 'learn', 'music', 10, 'medium', 'outdoors', 'medium', 'free', 'alone', 20, false, false, null, 'how to hand whistle owl call', 'published', 'seed', now()),
  ('learn-music-pucker-whistle-a-scale', 'Pucker whistle a scale', 'Learn to whistle a full major scale with your lips, keeping every note clear. Then whistle a simple tune all the way through without breaking.', 'learn', 'music', 10, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, 'how to whistle better', 'published', 'seed', now()),
  ('learn-music-learn-to-read-a-chord-box', 'Learn to read a chord box', 'Learn how a chord diagram shows strings, frets and fingers, then use one to play three chords you have never tried on any guitar or ukulele.', 'learn', 'music', 10, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'how to read guitar chord diagrams', 'published', 'seed', now()),
  ('learn-music-tab-reading-crash-course', 'Tab reading crash course', 'Learn to read guitar tab, where lines are strings and numbers are frets. Play the first riff of a song you love straight from a tab page.', 'learn', 'music', 15, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, 'how to read guitar tabs', 'published', 'seed', now()),
  ('learn-music-lead-sheet-decoding', 'Lead sheet decoding', 'Learn how a lead sheet combines one melody line with chord symbols above it. Find a lead sheet for a standard and play just the chords while humming the tune.', 'learn', 'music', 20, 'medium', 'indoors', 'low', 'free', 'alone', 20, false, false, null, 'how to read a lead sheet', 'published', 'seed', now()),
  ('learn-music-figured-bass-mystery', 'Figured bass mystery', 'Learn how baroque players read small numbers under the bass line to know which chords to fill in. Decode four bars with a cheat sheet.', 'learn', 'music', 30, 'insane', 'indoors', 'low', 'free', 'alone', 50, false, false, null, 'figured bass explained', 'published', 'seed', now()),
  ('learn-music-shape-note-singing-taster', 'Shape note singing taster', 'Learn about shape notes, where each scale step has its own shape, and sing a simple hymn tune using fa, sol and la. Find a recording of a sacred harp group to hear the raw power.', 'learn', 'music', 25, 'medium', 'anywhere', 'medium', 'free', 'either', 20, false, false, null, 'shape note singing explained', 'published', 'seed', now()),
  ('learn-music-learn-the-solfege-ladder', 'Learn the solfège ladder', 'Sing do, re, mi, fa, sol, la, ti, do up and down, then jump around the ladder as a friend points to random rungs. Learn to land each one in tune.', 'learn', 'music', 10, 'easy', 'anywhere', 'medium', 'free', 'either', 10, false, false, null, 'solfege for beginners', 'published', 'seed', now()),
  ('learn-music-moveable-do-song-decode', 'Moveable do song decode', 'Learn to sing a familiar tune like Twinkle Twinkle using solfège syllables instead of words. Then try it starting on a different note to see why do can move.', 'learn', 'music', 10, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
