  ('learn-productivity-washing-machine-eco-programme-decoded', 'Washing machine eco programme decoded', 'Dig out your washing machine manual and learn what each programme does, especially why eco cycles run longer but use less energy. Pick a default programme for everyday loads and stick a note on the machine.', 'learn', 'productivity', 15, 'easy', 'indoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
