  ('learn-productivity-learn-your-consumer-rights-for-a-return', 'Learn your consumer rights for a return', 'Read a plain-English summary of consumer rights for faulty goods, then use it to deal with one broken item you have been ignoring.', 'learn', 'productivity', 25, 'medium', 'computer', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
