  ('learn-productivity-sew-a-button-that-stays-put', 'Sew a button that stays put', 'Learn the shank method for sewing on a button so it does not pull loose, then fix every loose button in your wardrobe.', 'learn', 'productivity', 20, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, 'how to sew on a button with a shank', 'published', 'seed', now()),
  ('learn-productivity-iron-on-patch-for-a-worn-jeans-knee', 'Iron-on patch for a worn jeans knee', 'Learn how iron-on patches bond, cut one with rounded corners and fix it inside a pair of jeans with a worn knee. Add a few hand stitches round the edge so it lasts.', 'learn', 'productivity', 25, 'easy', 'indoors', 'low', 'paid', 'alone', 10, false, false, 'Keep the iron upright between uses and switch it off when finished.', null, 'published', 'seed', now()),
  ('learn-productivity-close-a-split-seam-with-a-backstitch', 'Close a split seam with a backstitch', 'Learn the backstitch, the strongest hand stitch, then turn a pillowcase or shirt with a split seam inside out and close the gap with small even stitches.', 'learn', 'productivity', 20, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, 'how to backstitch by hand', 'published', 'seed', now()),
