  ('learn-productivity-learn-safe-lifting-before-moving-furniture', 'Learn safe lifting before moving furniture', 'Learn the bent-knee, close-to-the-body lift from a guide, practise it on an empty box, then use it with a friend to rearrange one heavy piece of furniture.', 'learn', 'productivity', 30, 'easy', 'indoors', 'high', 'free', 'with_friends', 10, false, false, 'Clear the path first and never lift something you cannot comfortably hold.', 'safe manual handling technique', 'published', 'seed', now()),
  ('learn-productivity-top-to-bottom-speed-clean-method', 'Top-to-bottom speed clean method', 'Learn the professional rule of cleaning from the highest surfaces down and left to right round a room. Race through one room with it against a timer and see if it beats your usual order.', 'learn', 'productivity', 25, 'easy', 'indoors', 'high', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
