  ('learn-productivity-edge-a-lawn-with-a-half-moon-tool', 'Edge a lawn with a half-moon tool', 'Learn how to cut a crisp lawn edge with a half-moon edger or spade along a taut string line. Do one border and stand back to admire the difference.', 'learn', 'productivity', 45, 'medium', 'outdoors', 'high', 'paid', 'alone', 20, false, false, 'Wear sturdy shoes and keep feet clear of the blade.', null, 'published', 'seed', now()),
  ('learn-productivity-paint-a-wall-with-the-w-method', 'Paint a wall with the W method', 'Learn how decorators roll paint on in a W shape and fill it in without lifting the roller. Paint one feature wall or a spare board and check for missed patches in daylight.', 'learn', 'productivity', 120, 'medium', 'indoors', 'high', 'paid', 'either', 20, false, false, 'Open windows for ventilation while painting.', 'how to paint a wall with a roller', 'published', 'seed', now()),
