  ('music-productivity-learn-the-roadie-cable-coil', 'Learn the roadie cable coil', 'Learn the over-under coil roadies use, then practise it on every audio lead in the drawer so none of them ever knots again. Wrap each one with a strip of tape that says what it is and how long.', 'music', 'productivity', 25, 'easy', 'indoors', 'medium', 'free', 'alone', 10, false, false, null, 'over under cable coiling technique', 'published', 'seed', now()),
