  ('music-productivity-sunday-progress-recording', 'Sunday progress recording', 'Every Sunday for a month, record thirty seconds of the same piece and save it with the date in its file name. On the last Sunday, play all four back in order and hear the progress.', 'music', 'productivity', 10, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-five-minute-daily-practice-pact', 'Five-minute daily practice pact', 'Promise yourself just five focused minutes on your instrument every day this week and tick a box each time. Small enough that you cannot talk yourself out of it.', 'music', 'productivity', 5, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
