) values
  ('music-productivity-pop-song-power-nap-timer', 'Pop-song power nap timer', 'Make a calm playlist exactly twenty minutes long, lie down, and get up when the final song ends. Write your next task before you rest.', 'music', 'productivity', 20, 'easy', 'indoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-stand-up-desk-song-rule', 'Stand-up desk song rule', 'Every time the playlist hits a new song, switch between sitting and standing at your desk. Track how you feel by the end of the afternoon.', 'music', 'productivity', 60, 'easy', 'indoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-hydration-on-the-hook', 'Hydration on the hook', 'Drink a glass of water whenever your work playlist reaches a song by a band you have seen live. A cheerful reminder to keep sipping.', 'music', 'productivity', 60, 'easy', 'anywhere', 'low', 'free', 'either', 15, true, false, null, null, 'published', 'seed', now()),
  ('music-productivity-pick-up-ten-things-per-chorus', 'Pick up ten things per chorus', 'Every time a chorus comes on today, pick up ten things that are out of place. By evening the house will be quietly tidier.', 'music', 'productivity', 5, 'easy', 'indoors', 'high', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-doorstep-delivery-dash-song', 'Doorstep delivery dash song', 'When a delivery arrives, unpack it, flatten the box and put the item away before the song you were playing ends. No boxes allowed to linger.', 'music', 'productivity', 3, 'easy', 'indoors', 'high', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-vocal-sirens-before-a-phone-call', 'Vocal sirens before a phone call', 'Do thirty seconds of vocal sirens before a call you have been dreading. Your voice will be warmer and you will feel braver.', 'music', 'productivity', 1, 'easy', 'anywhere', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-lip-trill-before-speaking', 'Lip trill before speaking', 'Before a meeting or presentation, do a lip trill up and down your range for one minute. It relaxes your face and voice like it does for singers.', 'music', 'productivity', 1, 'easy', 'anywhere', 'medium', 'free', 'alone', 10, false, false, null, 'lip trill vocal exercise', 'published', 'seed', now()),
  ('music-productivity-presentation-rehearsal-with-walk-on-music', 'Presentation rehearsal with walk-on music', 'Rehearse your next presentation from the top with a ten-second walk-on song before you start. Time the talk and cut anything over the limit.', 'music', 'productivity', 30, 'medium', 'indoors', 'high', 'free', 'either', 25, true, false, null, null, 'published', 'seed', now()),
  ('music-productivity-speech-pacing-to-a-metronome', 'Speech pacing to a metronome', 'Read your speech aloud with a metronome at a slow tempo, one word per click, then speed up. It cures rushing when you are nervous.', 'music', 'productivity', 15, 'medium', 'anywhere', 'medium', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-interview-confidence-song', 'Interview confidence song', 'Choose one song that makes you feel unstoppable and listen to it before every interview, exam or difficult task this month. Play it as a ritual.', 'music', 'productivity', 4, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-bravery-playlist-for-hard-tasks', 'Bravery playlist for hard tasks', 'Build a playlist of eight songs that make you feel brave and use it only when starting the task you have avoided longest.', 'music', 'productivity', 20, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-calm-playlist-for-difficult-emails', 'Calm playlist for difficult emails', 'Make a calm playlist and save it only for writing tricky emails and messages. Over time just pressing play will steady your tone.', 'music', 'productivity', 15, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-rhythm-writing-sprint', 'Rhythm writing sprint', 'Write without stopping for the length of a fast song, then edit for the length of a slow one. Repeat three times on your essay or report.', 'music', 'productivity', 25, 'medium', 'computer', 'medium', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-word-count-per-song', 'Word count per song', 'Set a target of one hundred words for every song on your writing playlist. Keep a tally on paper beside your keyboard.', 'music', 'productivity', 45, 'medium', 'computer', 'medium', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
