  ('music-productivity-password-manager-evening', 'Password manager evening', 'Set up a password manager with calming music on and move your ten most important logins into it. Play one celebratory song when done.', 'music', 'productivity', 60, 'medium', 'computer', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-bills-autopay-set-up-with-a-playlist', 'Bills autopay set-up with a playlist', 'Spend one playlist setting up direct debits and reminders for every regular bill. Each song is one bill.', 'music', 'productivity', 40, 'medium', 'computer', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-calendar-clear-out-album', 'Calendar clear-out album', 'Go through the next month in your calendar while an album plays, deleting dead events and adding travel time. Finish before the last track.', 'music', 'productivity', 30, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
