  ('music-productivity-bookmark-tidy-to-a-mix', 'Bookmark tidy to a mix', 'Sort your browser bookmarks into a few folders and delete dead links while a dance mix plays. Finish with a bookmark bar you can actually use.', 'music', 'productivity', 25, 'easy', 'computer', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
