  ('music-productivity-inbox-triage-disco', 'Inbox triage disco', 'Put on a disco track and play inbox triage: every email is either deleted, done in under two minutes or put on a list, all on the beat.', 'music', 'productivity', 20, 'easy', 'computer', 'medium', 'free', 'alone', 15, true, false, null, null, 'published', 'seed', now()),
