  ('music-productivity-do-not-disturb-playlist-sign', 'Do-not-disturb playlist sign', 'Make a sign for your door that says what you are listening to and that you are in focus mode until it ends. Flatmates love knowing when you are free.', 'music', 'productivity', 10, 'easy', 'indoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-focus-music-for-a-group-work-session', 'Focus music for a group work session', 'At a group study or work session, one person plays quiet instrumental music from a speaker and everyone works silently until the album ends.', 'music', 'productivity', 60, 'easy', 'indoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-library-study-with-headphones-and-a-goal', 'Library study with headphones and a goal', 'Go to the library with headphones and one album, sit at a quiet desk and set a clear goal to finish before the music does.', 'music', 'productivity', 60, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
