  ('music-productivity-silence-versus-music-experiment', 'Silence versus music experiment', 'Do a twenty-minute task in silence, then a similar one with music. Note which went faster and which felt nicer.', 'music', 'productivity', 45, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('music-productivity-tempo-matching-for-tasks', 'Tempo matching for tasks', 'Match your music tempo to the task: slow for reading, mid for writing, fast for tidying. Try it for one afternoon and keep notes.', 'music', 'productivity', 120, 'medium', 'anywhere', 'medium', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
