  ('outdoors-gaming-silent-chase', 'Silent chase', 'Play chase where nobody may make a sound. Any squeal, giggle or shout sends you straight to being the catcher. Much harder than it sounds once someone gets close.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-zombie-walk-tag', 'Zombie walk tag', 'The zombies may only walk with stiff legs while survivors can run, but survivors must touch three corner markers before they are safe. Every tagged survivor becomes a zombie.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'high', 'free', 'with_friends', 15, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-treasure-guard-chase', 'Treasure guard chase', 'One guard protects a pile of pine cones in the centre. Raiders sneak in to carry off a cone at a time. Tagged raiders drop their cone and go back to the edge.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-wolf-o-clock-in-the-garden', 'Wolf o''clock in the garden', 'Ask the wolf the time as you creep forward. The wolf answers a number of steps until shouting dinner time and chasing everyone back to the fence. A classic for mixed ages.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, 'Clear toys and tools off the lawn before the chase.', null, 'published', 'seed', now()),
  ('outdoors-gaming-ladder-hop-off', 'Ladder hop-off', 'Lay out a rope ladder shape on the grass. Two teams hop across from opposite ends. When they meet, they play rock paper scissors and the loser goes back to the start.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-balloon-on-the-ankle-stomp', 'Balloon-on-the-ankle stomp', 'Tie a balloon to everyone''s ankle with string. Try to pop rival balloons by stamping while protecting your own. Last balloon standing wins, then pick up every scrap.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'high', 'paid', 'with_friends', 15, true, false, 'Stamp on balloons, not feet, and collect all the rubber afterwards.', null, 'published', 'seed', now()),
  ('outdoors-gaming-walk-only-race-to-the-oak', 'Walk-only race to the oak', 'Everyone races to a far tree, but walking only. Anyone caught with both feet off the ground by the judge goes back ten steps. The silly speed-walking is the fun.', 'outdoors', 'gaming', 5, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-hop-scotch-chase', 'Hop-scotch chase', 'Chalk a long hopscotch on the pavement outside your home. The chaser must hop the grid exactly before they can leave it, so runners get a few seconds of head start each time.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Use a quiet private drive or playground, never a road.', null, 'published', 'seed', now()),
  ('outdoors-gaming-animal-voice-chase', 'Animal-voice chase', 'The catcher shouts an animal and everyone must move like it until the next call. Kangaroos hop, snakes slither and penguins waddle while still trying to dodge the tag.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'high', 'free', 'with_friends', 15, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-buddy-rescue-tag', 'Buddy rescue tag', 'Tagged players sit down and can only be freed by two free players holding hands around them and counting to five. The catcher wins by freezing everyone.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now())
on conflict (slug) do update set
  title = excluded.title,
  description = excluded.description,
  category = excluded.category,
  secondary_category = excluded.secondary_category,
  duration_minutes = excluded.duration_minutes,
  difficulty = excluded.difficulty,
  location = excluded.location,
  energy_level = excluded.energy_level,
  cost_type = excluded.cost_type,
  people_type = excluded.people_type,
  xp_reward = excluded.xp_reward,
  is_chaos = excluded.is_chaos,
  is_featured = excluded.is_featured,
  safety_note = excluded.safety_note,
  video_query = excluded.video_query
where public.activities.source = 'seed';

insert into public.activities (
  slug, title, description, category, secondary_category, duration_minutes, difficulty, location,
  energy_level, cost_type, people_type, xp_reward, is_chaos, is_featured, safety_note,
  video_query, status, source, published_at
) values
  ('outdoors-gaming-bench-to-bench-sprint-game', 'Bench-to-bench sprint game', 'In a park with several benches, the caller names a bench and everyone races to touch it. The last to arrive becomes the next caller. Five rounds, no repeats.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Pick benches on grass away from paths with cyclists.', null, 'published', 'seed', now()),
  ('outdoors-gaming-line-only-chase', 'Line-only chase', 'On a playground or sports court, everyone may move only along the painted lines. The catcher too. Jumping across a gap counts as out. A puzzle and a chase at once.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-statues-at-the-bandstand', 'Statues at the bandstand', 'One player turns their back and counts. Everyone else dances and freezes in a statue the moment they turn. Wobblers are out. Last statue becomes the counter.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-chase-with-a-rule-change-every-minute', 'Chase with a rule change every minute', 'Set a phone timer to buzz each minute. On every buzz the catcher announces a new rule, such as hopping only or left hands up. Players must adapt mid-sprint.', 'outdoors', 'gaming', 15, 'medium', 'outdoors', 'high', 'free', 'with_friends', 25, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-kite-tail-chase', 'Kite-tail chase', 'Each player tucks a long ribbon into their back pocket. Pull other tails to collect them while keeping your own. Tied ribbons are banned. Most ribbons after three minutes wins.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'high', 'paid', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-three-base-flag-dash', 'Three-base flag dash', 'Make three home bases in a triangle with jumpers. Teams try to get a runner around all three bases while defenders tag. Each lap scores a point.', 'outdoors', 'gaming', 30, 'medium', 'outdoors', 'high', 'free', 'with_friends', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-sharks-and-minnows-on-the-grass', 'Sharks and minnows on the grass', 'The shark stands in the middle of the field. On the call of fishies, the minnows run to the far side. Tagged minnows become seaweed who can tag from where they stand.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-mirror-runner', 'Mirror runner', 'Pair up. One runs anywhere in a marked area while the other copies their exact path and moves a few steps behind. Swap after one minute and judge who shook off their shadow best.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-pocket-torch-tag-after-dusk', 'Pocket-torch tag after dusk', 'In a garden after dark, the catcher tags with a torch beam. Anyone lit up for a full second is caught. Hiders crouch behind bushes and dash between them.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, 'Play only in a familiar enclosed garden and never shine the torch in eyes.', null, 'published', 'seed', now()),
  ('outdoors-gaming-glow-stick-capture', 'Glow-stick capture', 'Teams wear glow sticks on wrists and guard a lantern at each end of a field after sunset. Grab the other team''s lantern and bring it home without getting tagged.', 'outdoors', 'gaming', 45, 'medium', 'outdoors', 'high', 'paid', 'with_friends', 20, false, false, 'Walk the field in daylight first and check for holes and hazards.', null, 'published', 'seed', now()),
  ('outdoors-gaming-ninja-freeze', 'Ninja freeze', 'Stand in a circle. In turn, each player makes one swift move to tap an opponent''s hand, then freezes. The defender may dodge with one move. Hands tapped are lost.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-camouflage-freeze-on-the-hillside', 'Camouflage freeze on the hillside', 'The seeker stays on a high spot and counts to thirty while everyone hides in long grass. Then hiders creep forward between the seeker''s looks. First to touch the seeker wins.', 'outdoors', 'gaming', 25, 'medium', 'outdoors', 'medium', 'free', 'with_friends', 20, false, false, 'Agree a call that ends the game so nobody wanders out of earshot.', null, 'published', 'seed', now()),
  ('outdoors-gaming-spotlight-sardines', 'Spotlight sardines', 'One person hides somewhere in the garden after dusk. Everyone else searches, and anyone who finds the hider squeezes in silently with them, until the last searcher is left.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, 'Keep the hiding area small and familiar after dark.', null, 'published', 'seed', now()),
  ('outdoors-gaming-hide-and-seek-with-only-one-hiding-rule', 'Hide-and-seek with only one hiding rule', 'Before each round, the hider picks one secret rule for their spot, such as touching something green. Seekers who find them guess the rule for a bonus point.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-kick-the-can-in-the-cul-de-sac', 'Kick-the-can in the cul-de-sac', 'Put a tin on a garden lawn. The seeker counts and hunts while hiders try to sneak back and kick the can, freeing everyone caught. A long-running classic for evenings.', 'outdoors', 'gaming', 30, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Play in a garden or park, keeping clear of parked cars and roads.', null, 'published', 'seed', now()),
  ('outdoors-gaming-hide-a-noisemaker-hunt', 'Hide-a-noisemaker hunt', 'Hide a phone playing a quiet, looping tune somewhere in the garden. Seekers have two minutes to find it by sound alone. The hider gets a point for each minute it stays hidden.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-reverse-park-search', 'Reverse park search', 'Instead of hiding, the seeker hides a bright clothes peg and gives three spoken clues. Hunters race to find it. Whoever finds it hides it next with fresh clues.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-statue-hide-and-seek', 'Statue hide-and-seek', 'Hiders must stay in plain sight but frozen as statues among real garden ornaments or trees. The seeker hunts for any movement. Blinking is allowed, giggling is not.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'low', 'free', 'with_friends', 15, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-hide-in-the-open', 'Hide in the open', 'Players stand somewhere visible in a small park and try to blend in by copying what nearby things do, like a lamppost or a bush. Seekers name each disguise they spot.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'low', 'free', 'with_friends', 15, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-last-one-home', 'Last one home', 'One seeker guards a tree called home. Hiders scatter, then must get back to home without being seen and called by name. Anyone called out helps the seeker spot others.', 'outdoors', 'gaming', 25, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-hiders-choose-the-map', 'Hiders choose the map', 'Draw a rough map of the garden in chalk on the patio. Each hider secretly marks an X in a notebook for where they will hide. If the seeker searches that spot first, they lose a point.', 'outdoors', 'gaming', 20, 'medium', 'outdoors', 'low', 'free', 'with_friends', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-blindfold-scent-trail', 'Blindfold scent trail', 'One player wipes a strong-smelling herb like mint along a few fence posts. A blindfolded partner, guided by a spotter for safety, follows the scent to the end.', 'outdoors', 'gaming', 15, 'medium', 'outdoors', 'low', 'free', 'with_friends', 20, false, false, 'The spotter keeps a hand on the shoulder of the blindfolded player at all times.', null, 'published', 'seed', now()),
  ('outdoors-gaming-bird-call-hide-and-seek', 'Bird-call hide-and-seek', 'Hiders whistle a simple two-note call every thirty seconds. The seeker uses only these calls to track them through the trees. Change the call each round to keep it tricky.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, 'Agree a boundary and a whistle signal that ends the game.', null, 'published', 'seed', now()),
  ('outdoors-gaming-hide-behind-your-own-shadow', 'Hide behind your own shadow', 'Around midday on a sunny day, the seeker stands still while hiders try to keep their whole shadow inside the shade of trees or walls. Anyone with a shadow poking out is spotted.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-teddy-rescue-mission', 'Teddy rescue mission', 'Hide a cuddly toy in the garden. The finder must carry it home to the porch while the others try to tag it from them. Whoever holds it at the porch hides it next.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-moving-hiders', 'Moving hiders', 'Hiders may swap hiding spots whenever the seeker is facing away, but only by crawling. The seeker scores a point for each hider caught mid-move.', 'outdoors', 'gaming', 20, 'medium', 'outdoors', 'medium', 'free', 'with_friends', 25, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-hide-and-seek-with-a-five-word-clue', 'Hide-and-seek with a five-word clue', 'The hider whispers a five-word description of their spot to a referee before hiding. If the seeker gives up, the referee reads it aloud, and the seeker has one more minute to find them.', 'outdoors', 'gaming', 20, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-hidden-in-the-hedge-maze', 'Hidden in the hedge maze', 'Visit a hedge maze and play hide-and-seek inside it with a time limit. Seekers must also find their way back to the entrance, and the first one out after finding a hider wins.', 'outdoors', 'gaming', 60, 'medium', 'outdoors', 'medium', 'paid', 'with_friends', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-peg-hunt-hide', 'Peg-hunt hide', 'Clip twenty coloured clothes pegs on bushes and fences around the garden in under a minute. The finder has three minutes to collect them. Swap and see who hid them better.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-bunker-spotting-game', 'Bunker spotting game', 'On a big open field, a seeker stands in the middle with eyes closed. Hiders lie flat in the grass anywhere they like. The seeker opens their eyes and spins once, naming everyone visible.', 'outdoors', 'gaming', 5, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-hot-and-cold-with-a-whistle', 'Hot and cold with a whistle', 'A hider places a small toy in the park and guides the finder only with whistle blasts, short for cold and long for warm. No words allowed. Swap after it is found.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-sound-only-seeker', 'Sound-only seeker', 'The seeker wears a blindfold and sits on a picnic blanket. Hiders must move to a new spot quietly while the seeker points at sounds. Every correct point captures a hider.', 'outdoors', 'gaming', 10, 'easy', 'outdoors', 'low', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-easy-rated-cache-for-a-beginner-hunt', 'Easy-rated cache for a beginner hunt', 'Install a free geocaching app, pick the simplest cache within walking distance and go and find it. Sign the logbook, put it back exactly as you found it and log the find.', 'outdoors', 'gaming', 60, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, 'geocaching for beginners how to find a cache', 'published', 'seed', now()),
  ('outdoors-gaming-hide-a-geocache-of-your-own', 'Hide a geocache of your own', 'Pack a small waterproof box with a logbook and a pencil, choose a public spot with the landowner''s permission and submit it to a geocaching site so strangers can hunt for it.', 'outdoors', 'gaming', 120, 'hard', 'outdoors', 'medium', 'paid', 'alone', 35, false, false, 'Only hide caches where it is allowed, never on private land or near rail lines.', null, 'published', 'seed', now()),
  ('outdoors-gaming-multi-stage-cache-day', 'Multi-stage cache day', 'Choose a multi-cache, where each stage gives you the coordinates of the next. Plan a route, take notes at every stage and see if you can solve it before your snacks run out.', 'outdoors', 'gaming', 180, 'hard', 'outdoors', 'medium', 'free', 'either', 35, false, false, 'Tell someone your route and take water and a charged phone.', null, 'published', 'seed', now()),
  ('outdoors-gaming-puzzle-cache-at-the-park-bench', 'Puzzle cache at the park bench', 'Pick a mystery geocache whose coordinates come from a puzzle. Solve it at home, then walk out to check your answer on the ground. The walk is your victory lap.', 'outdoors', 'gaming', 90, 'hard', 'outdoors', 'medium', 'free', 'alone', 35, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-travel-bug-relay', 'Travel bug relay', 'Find a geocache that holds a trackable tag, move it on to another cache further along its journey, and log where it went. Check back in a month to see how far it travelled.', 'outdoors', 'gaming', 90, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-walk-a-giant-smiley-onto-the-map', 'Walk a giant smiley onto the map', 'Plan a route whose tracked line makes a smiling face, with two short loops for eyes. Record it with a fitness app and award yourself marks for roundness.', 'outdoors', 'gaming', 60, 'medium', 'outdoors', 'medium', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-letterbox-stamp-hunt', 'Letterbox stamp hunt', 'Look up a letterboxing trail on moorland or in a country park. Follow the clues to hidden boxes, stamp your notebook with each box''s stamp and leave your own mark in theirs.', 'outdoors', 'gaming', 150, 'medium', 'outdoors', 'medium', 'paid', 'either', 20, false, false, 'Check the weather, carry a map and stay on public paths.', null, 'published', 'seed', now()),
  ('outdoors-gaming-make-your-own-letterbox-stamp', 'Make your own letterbox stamp', 'Carve a simple design into a soft rubber block or an eraser, then take it on a letterboxing trail and use it as your signature stamp in every logbook you find.', 'outdoors', 'gaming', 45, 'medium', 'outdoors', 'low', 'paid', 'alone', 20, false, false, 'Carve away from your fingers with a lino cutter, slowly.', null, 'published', 'seed', now()),
  ('outdoors-gaming-pokestop-circuit', 'Pokestop circuit', 'Plan a walking loop in a location-based monster-catching game that passes as many stops as possible in thirty minutes. Count the items collected and try to beat it next week.', 'outdoors', 'gaming', 30, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, 'Look up from the screen at every crossing.', null, 'published', 'seed', now()),
  ('outdoors-gaming-raid-day-with-a-stranger-team', 'Raid day with a stranger team', 'Join a public raid in a location-based phone game at a local landmark. Coordinate with the other players who turn up and celebrate together when the boss falls.', 'outdoors', 'gaming', 30, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, 'Meet in busy public places and never share your home address.', null, 'published', 'seed', now()),
  ('outdoors-gaming-portal-capture-walk', 'Portal-capture walk', 'In a territory-control phone game, walk a neighbourhood loop capturing landmarks for your team. Keep a note of which ones flip back overnight.', 'outdoors', 'gaming', 45, 'medium', 'outdoors', 'medium', 'free', 'alone', 20, false, false, 'Stay aware of traffic and do not stand in the road while playing.', null, 'published', 'seed', now()),
  ('outdoors-gaming-augmented-reality-monster-stroll', 'Augmented-reality monster stroll', 'Open an AR game where creatures appear in your surroundings and take a walk through three different types of terrain, such as park, canal and high street, to see what changes.', 'outdoors', 'gaming', 40, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, 'Keep to pavements and look up regularly.', null, 'published', 'seed', now()),
  ('outdoors-gaming-steps-only-egg-hatching', 'Steps-only egg hatching', 'Pick one virtual egg in a location game and refuse to open the app again until you have walked far enough to hatch it. Guess how long it will take before you set out.', 'outdoors', 'gaming', 45, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-grid-square-bagging', 'Grid square bagging', 'Use an online map grid of one-kilometre squares and visit three you have never set foot in. Take a photo in each as proof and mark them on a printed map.', 'outdoors', 'gaming', 120, 'medium', 'outdoors', 'medium', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-confluence-point-quest', 'Confluence point quest', 'Find the nearest point where a whole-number line of latitude meets a line of longitude. Plan a legal route as close as you can get, then photograph your position.', 'outdoors', 'gaming', 180, 'hard', 'outdoors', 'medium', 'free', 'either', 35, false, false, 'Stay on public rights of way and turn back if the route is not allowed.', null, 'published', 'seed', now()),
  ('outdoors-gaming-trig-point-bingo', 'Trig point bingo', 'Look up the trig pillars within an hour''s travel. Visit as many as you can in a day and photograph your hand on each one. Five in a day is a good score.', 'outdoors', 'gaming', 300, 'hard', 'outdoors', 'high', 'free', 'either', 35, false, false, 'Plan the route, carry water and check the forecast before hill walks.', null, 'published', 'seed', now()),
  ('outdoors-gaming-random-coordinate-adventure', 'Random-coordinate adventure', 'Use a random point generator app to pick a spot within two kilometres. Go there, find the most interesting thing within a minute''s walk and photograph it.', 'outdoors', 'gaming', 60, 'easy', 'outdoors', 'medium', 'free', 'either', 15, true, false, 'Skip any point on private land or across busy roads.', null, 'published', 'seed', now()),
  ('outdoors-gaming-map-flip-walk', 'Map-flip walk', 'At every junction, flip a coin. Heads go left, tails go right. After thirty minutes, use your phone map only to find the way home and see how lost you got.', 'outdoors', 'gaming', 45, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, 'Stay in areas you know are safe and take a charged phone.', null, 'published', 'seed', now()),
  ('outdoors-gaming-dice-route-wander', 'Dice-route wander', 'Roll a die at each corner: one or two turn left, three or four go straight, five or six turn right. Score a point for every new street you have never walked down.', 'outdoors', 'gaming', 40, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-streetview-guess-walk', 'Streetview guess walk', 'Have a friend send you a street-level photo from somewhere in your town. Walk out and find the exact spot, then send them a photo from the same angle.', 'outdoors', 'gaming', 60, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-photo-match-challenge', 'Photo-match challenge', 'A friend picks five old photos of your town from a local history page. You go and stand where each was taken and match the angle. Score by how close the crop is.', 'outdoors', 'gaming', 90, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-step-count-duel', 'Step-count duel', 'Agree with a friend to start counting steps at noon. Both go out for an hour wherever you like. At one o''clock, compare counts and the higher score chooses next week''s route.', 'outdoors', 'gaming', 60, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-gaming-parkrun-personal-best-game', 'Parkrun personal-best game', 'Turn your local free weekly timed run into a game by picking a rival with a similar time from last week''s results and trying to finish ahead of them.', 'outdoors', 'gaming', 45, 'medium', 'outdoors', 'high', 'free', 'alone', 20, false, false, 'Warm up first and run at your own pace if you feel unwell.', null, 'published', 'seed', now()),
  ('outdoors-gaming-stopwatch-loop-challenge', 'Stopwatch loop challenge', 'Pick a loop around your block and time yourself walking it. Each day, try to beat your time by five seconds, walking only. Log the times on your phone and chart the streak.', 'outdoors', 'gaming', 15, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, 'Look both ways at every crossing, however fast you are going.', null, 'published', 'seed', now()),
