  ('outdoors-learn-fox-signs-walk', 'Fox signs walk', 'Walk at dusk round a park edge and learn the signs of foxes: musky scent, narrow paths through hedges, twisted droppings and the scream in winter.', 'outdoors', 'learn', 40, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Do not approach or feed foxes.', null, 'published', 'seed', now()),
  ('outdoors-learn-deer-rut-viewing-trip', 'Deer rut viewing trip', 'In October, visit a deer park and learn about the rut from a safe distance: roaring, parallel walking and antler clashes between stags.', 'outdoors', 'learn', 120, 'easy', 'outdoors', 'medium', 'paid', 'with_friends', 10, false, false, 'Stay at least fifty metres away from stags during the rut.', null, 'published', 'seed', now()),
