  ('outdoors-learn-rabbit-warren-observation', 'Rabbit warren observation', 'Find a warren on a hillside and sit downwind at dawn or dusk. Learn about rabbit sentries and the white tail flash that warns the colony.', 'outdoors', 'learn', 45, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-learn-animal-scat-id-cards', 'Animal scat ID cards', 'Learn to recognise droppings of rabbits, deer, foxes and birds from pictures, then look for them on a walk without touching any. Award points for each confirmed sighting.', 'outdoors', 'learn', 30, 'medium', 'outdoors', 'medium', 'free', 'with_friends', 25, true, false, 'Look only, do not touch.', null, 'published', 'seed', now()),
  ('outdoors-learn-badger-sett-signs', 'Badger sett signs', 'Visit a known badger area in daylight and learn the signs: large D-shaped holes, spoil heaps with bedding, scratching trees and latrine pits.', 'outdoors', 'learn', 60, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Do not block, disturb or dig near a sett.', null, 'published', 'seed', now()),
  ('outdoors-learn-night-visitor-sand-tray', 'Night visitor sand tray', 'Rake a tray of fine damp sand smooth at the edge of a lawn last thing at night. In the morning, learn to read whatever crossed it: paw pads, bird toes, slug trails.', 'outdoors', 'learn', 10, 'medium', 'outdoors', 'low', 'free', 'either', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-learn-grey-seal-colony-visit', 'Grey seal colony visit', 'Visit a coast where grey seals haul out and learn to tell males, females and white-coated pups apart through binoculars from a viewing point.', 'outdoors', 'learn', 120, 'easy', 'outdoors', 'medium', 'paid', 'either', 10, false, false, 'Keep well back from seals and pups.', null, 'published', 'seed', now()),
  ('outdoors-learn-frogspawn-or-toadspawn', 'Frogspawn or toadspawn', 'In early spring, visit a pond and learn the difference: frogs lay clumps, toads lay strings. Count the clumps and return weekly to watch the tadpoles develop.', 'outdoors', 'learn', 15, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, 'Look from the bank and wash your hands if you touch pond water.', null, 'published', 'seed', now()),
