  ('outdoors-learn-slow-worm-search', 'Slow worm search', 'Learn that slow worms are legless lizards, not snakes. Check under sheets of tin or roofing felt left on a sunny allotment, and lift each one gently.', 'outdoors', 'learn', 15, 'medium', 'outdoors', 'low', 'free', 'either', 20, false, false, 'Look but do not pick up reptiles.', null, 'published', 'seed', now()),
