  ('outdoors-learn-lizard-basking-census', 'Lizard basking census', 'On a warm morning, walk a heathland path and count common lizards basking on logs and boardwalks. Learn why reptiles need the sun to get going.', 'outdoors', 'learn', 45, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
