  ('outdoors-learn-caddis-fly-case-collection', 'Caddis fly case collection', 'Find caddis larvae in a stream and learn how each species builds its case from sand, twigs or shells. Photograph three different designs, then return them.', 'outdoors', 'learn', 25, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Stay in ankle-deep water with someone nearby.', null, 'published', 'seed', now()),
