  ('outdoors-learn-bird-of-prey-centre-visit', 'Bird of prey centre visit', 'Visit a bird of prey centre and watch a flying display. Learn how owls fly silently and why falcons dive so fast.', 'outdoors', 'learn', 150, 'easy', 'outdoors', 'low', 'paid', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-learn-rockpool-creature-checklist', 'Rockpool creature checklist', 'At low tide, explore rockpools and tick off a crab, a blenny, an anemone, a limpet and a starfish. Learn one survival trick each uses between tides.', 'outdoors', 'learn', 60, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, 'Check tide times, wear grippy shoes and put rocks back as you found them.', null, 'published', 'seed', now()),
