  ('outdoors-learn-seaweed-zones-on-a-rocky-shore', 'Seaweed zones on a rocky shore', 'Walk from top to bottom of a rocky shore at low tide and learn how seaweeds form bands: channelled wrack, spiral wrack, bladderwrack, then kelp.', 'outdoors', 'learn', 40, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Watch the tide and take care on slippery rocks.', null, 'published', 'seed', now()),
