  ('outdoors-productivity-paths-of-woodchip', 'Paths of woodchip', 'Barrow woodchip onto the paths between your veg beds and rake it level, so you can walk the plot in winter without sinking.', 'outdoors', 'productivity', 60, 'medium', 'outdoors', 'high', 'free', 'either', 20, false, false, 'Load the barrow only as heavy as you can steer.', null, 'published', 'seed', now()),
  ('outdoors-productivity-no-dig-bed-start', 'No-dig bed start', 'Lay cardboard over a weedy patch, soak it, and pile a thick layer of compost on top. Plant straight into it next month with no digging at all.', 'outdoors', 'productivity', 45, 'easy', 'outdoors', 'high', 'paid', 'either', 10, false, false, null, 'how to make a no dig garden bed', 'published', 'seed', now()),
  ('outdoors-productivity-bed-edge-boards', 'Bed edge boards', 'Screw wooden boards around a veg bed to stop the soil spilling onto the path. Check the corners are square with a tape measure.', 'outdoors', 'productivity', 60, 'medium', 'outdoors', 'medium', 'paid', 'either', 20, false, false, 'Wear gloves and keep fingers clear of the drill.', null, 'published', 'seed', now()),
  ('outdoors-productivity-fleece-cover-for-frost', 'Fleece cover for frost', 'Check the forecast, and if frost is coming, drape horticultural fleece over tender plants and pin it with stones. Lift it off again in the morning.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'medium', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-soil-ph-test', 'Soil pH test', 'Take a soil sample from three beds, mix with water in a test kit and note the pH of each. Now you know where the blueberries will be happy.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'low', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-worm-count-survey', 'Worm count survey', 'Dig one spadeful of soil from each bed, count the earthworms and write it down. More worms means healthier soil, and you can track it each year.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-apple-harvest-by-the-box', 'Apple harvest by the box', 'Pick apples with a twist and lift, sort them into perfect for storage and bruised for eating now, and wrap each storer in newspaper.', 'outdoors', 'productivity', 45, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, 'Use a fruit picker on a pole rather than a wobbly ladder.', null, 'published', 'seed', now()),
  ('outdoors-productivity-pear-ripeness-check', 'Pear ripeness check', 'Lift a pear and tilt it level; if it snaps off easily, pick the tree. Bring them in to ripen on a windowsill.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-plum-tree-summer-prune', 'Plum tree summer prune', 'Cut back plum tree growth in summer, not winter, to avoid disease. Take out any dead wood and shorten long whippy shoots.', 'outdoors', 'productivity', 30, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Use loppers from the ground and never climb into the tree.', 'how to prune a plum tree', 'published', 'seed', now()),
  ('outdoors-productivity-blackcurrant-stem-renewal', 'Blackcurrant stem renewal', 'Cut a third of the oldest, darkest stems from each blackcurrant bush at the base so new fruiting shoots come through.', 'outdoors', 'productivity', 20, 'medium', 'outdoors', 'medium', 'free', 'alone', 20, false, false, null, 'how to prune blackcurrant bushes', 'published', 'seed', now()),
  ('outdoors-productivity-fruit-tree-grease-bands', 'Fruit tree grease bands', 'Wrap sticky grease bands round your apple tree trunks in autumn to catch the moths that climb up to lay eggs.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-wormery-feeding-round', 'Wormery feeding round', 'Add a tub of vegetable peelings to the wormery, cover with damp cardboard and drain off the liquid feed from the tap into a bottle.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-compost-temperature-check', 'Compost temperature check', 'Push a long thermometer or a metal rod into the middle of the compost heap. Hot means it is working; cold means it needs turning and more greens.', 'outdoors', 'productivity', 5, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-plot-photo-diary', 'Plot photo diary', 'Take the same photo of your plot from the same spot every Sunday. In a year you have a time-lapse and a record of what grew where.', 'outdoors', 'productivity', 5, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-salad-leaf-succession-sow', 'Salad leaf succession sow', 'Sow a short row of salad leaves every two weeks so there is always something ready. Today, sow the next row and pencil the following date on a calendar.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-allotment-tool-sharpening-queue', 'Allotment tool sharpening queue', 'Collect the hoes and spades from everyone''s shed on your row and sharpen the lot with a file in one afternoon. Return them gleaming.', 'outdoors', 'productivity', 60, 'medium', 'outdoors', 'medium', 'free', 'with_friends', 20, false, false, 'File away from your body and wear thick gloves.', null, 'published', 'seed', now()),
  ('outdoors-productivity-herb-bed-cut-back', 'Herb bed cut-back', 'Shear lavender, thyme and sage back after flowering to keep them bushy, avoiding the old woody bits. Sweep the cuttings into the compost.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-sunflower-support-ties', 'Sunflower support ties', 'Tie each tall sunflower to a stake at two points with soft twine before a windy week knocks them flat.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-water-by-the-root-rule', 'Water by the root rule', 'Water your veg beds at the base of each plant with a can, not the hose spray, timing how long the can lasts. Most beds need far less than you think.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-mulch-the-fruit-bushes', 'Mulch the fruit bushes', 'Spread a thick ring of compost or bark around each fruit bush, keeping it off the stems. Less weeding and less watering all summer.', 'outdoors', 'productivity', 25, 'easy', 'outdoors', 'high', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-planting-plan-on-a-fence', 'Planting plan on a fence', 'Paint a section of shed or fence with blackboard paint and chalk your bed-by-bed planting plan on it, updating as crops come and go.', 'outdoors', 'productivity', 40, 'easy', 'outdoors', 'low', 'paid', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-allotment-first-aid-tin', 'Allotment first aid tin', 'Put plasters, wipes, tweezers and antihistamine cream in a tin and leave it in the shed. Check it at the start of each season.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'low', 'paid', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-chard-and-spinach-cut', 'Chard and spinach cut', 'Cut the outer leaves of chard and spinach plants and leave the centres to keep growing. Bag them for the week''s meals before you leave.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-kale-stripping-for-the-freezer', 'Kale stripping for the freezer', 'Pick a big bag of kale, strip the leaves off the tough stems right there in the garden and blanch them for the freezer when you get in.', 'outdoors', 'productivity', 30, 'easy', 'anywhere', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-bolted-lettuce-clear', 'Bolted lettuce clear', 'Pull out every lettuce that has bolted to seed and put it on the compost, then rake the gap ready to sow something new.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-plot-clearance-race', 'Plot clearance race', 'Team up with a friend and clear a neglected allotment bed together, racing to fill the most barrows before the hour is up.', 'outdoors', 'productivity', 60, 'medium', 'outdoors', 'high', 'free', 'with_friends', 20, false, false, 'Gloves on and watch for hidden glass or wire.', null, 'published', 'seed', now()),
  ('outdoors-productivity-parsnip-winter-lift', 'Parsnip winter lift', 'Dig parsnips after the first frost, when they taste sweetest, and leave a row in the ground to lift as needed.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-bird-scarer-line', 'Bird scarer line', 'Tie strips of old CDs or foil to a string over seedbeds so they twist and flash and keep pigeons off. Use what is in the recycling.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-water-butt-to-beds-chain', 'Water butt to beds chain', 'Fill cans from the water butt and pass them along a chain of friends to the far beds. Time how fast the whole plot gets watered.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'high', 'free', 'with_friends', 15, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-seedling-name-game', 'Seedling name game', 'Remove the labels from a tray of seedlings, then try to identify each one by its leaves alone before checking. Re-label properly when you are done.', 'outdoors', 'productivity', 10, 'medium', 'outdoors', 'low', 'free', 'either', 25, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-allotment-harvest-swap-stall', 'Allotment harvest swap stall', 'Set up a trestle table at the allotment gate where plot holders swap surplus courgettes, beans and herbs. Agree a date and run it for an hour.', 'outdoors', 'productivity', 60, 'easy', 'outdoors', 'medium', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-fruit-bush-cuttings', 'Fruit bush cuttings', 'Take pencil-thick hardwood cuttings from currant bushes in autumn and push them into a trench. Next year they are free new bushes.', 'outdoors', 'productivity', 20, 'medium', 'outdoors', 'low', 'free', 'alone', 20, false, false, null, 'how to take hardwood cuttings', 'published', 'seed', now()),
  ('outdoors-productivity-chilli-plant-re-pot', 'Chilli plant re-pot', 'Move a chilli plant from its small pot into a bigger one on the patio table, firming fresh compost round it.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'paid', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-plot-shed-oil-up', 'Plot shed oil-up', 'Oil the hinges and padlock of your allotment shed and give the window a wipe so the door swings without a fight.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-weed-hoe-stroll', 'Weed hoe stroll', 'Walk between rows on a dry sunny morning slicing weeds just below the surface with a sharp hoe. The sun does the rest.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-allotment-rubbish-skip-run', 'Allotment rubbish skip run', 'Gather all the broken pots, old plastic and rusted wire from your plot and carry it to the communal skip in one go.', 'outdoors', 'productivity', 30, 'easy', 'outdoors', 'high', 'free', 'either', 10, false, false, 'Wear thick gloves for rusty metal.', null, 'published', 'seed', now()),
  ('outdoors-productivity-gardener-s-year-planner-page', 'Gardener''s year planner page', 'Sit on an upturned crate at the plot and list what you sow, plant and harvest each month, based on what you have now. Stick it inside the shed door.', 'outdoors', 'productivity', 30, 'medium', 'outdoors', 'low', 'free', 'either', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-plot-to-plate-menu', 'Plot-to-plate menu', 'Walk the plot and plan the next five dinners only from what is ready to pick right now. Write the menu on the back of a seed packet.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-beetroot-pull-and-twist', 'Beetroot pull and twist', 'Pull golf-ball beetroot and twist the leaves off rather than cutting, so they do not bleed. Keep the young leaves for salad.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-dry-pods-for-next-year', 'Dry pods for next year', 'Leave the last few beans on the plant to dry to brown, then pod them and store the seeds in a labelled paper envelope for next year.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, 'how to save bean seeds', 'published', 'seed', now()),
  ('outdoors-productivity-bed-by-bed-timed-weed', 'Bed-by-bed timed weed', 'Set a timer for ten minutes per bed and weed only that bed until it rings, then move on. You clear far more without getting fed up.', 'outdoors', 'productivity', 50, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-tomato-blight-check', 'Tomato blight check', 'Check your outdoor tomatoes for brown patches on leaves and stems. Cut off and bin any affected bits (not the compost) to stop it spreading.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-talking-to-the-plants-inspection', 'Talking-to-the-plants inspection', 'Walk the beds out loud like an inspector, giving each crop a verdict and a job: water, feed, pick or ignore. Write the jobs down as you go.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'either', 15, true, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-scarify-the-lawn-by-hand', 'Scarify the lawn by hand', 'Drag a spring-tine rake hard across the lawn in two directions to pull out the dead thatch and moss. Fill a barrow with what comes up and feel the burn in your arms.', 'outdoors', 'productivity', 60, 'medium', 'outdoors', 'high', 'free', 'alone', 20, false, false, 'Take breaks and swap hands often to spare your back.', 'how to scarify a lawn by hand', 'published', 'seed', now()),
  ('outdoors-productivity-aerate-with-a-garden-fork', 'Aerate with a garden fork', 'Push a garden fork into compacted bits of lawn every hand''s width and wiggle it back, so air and rain reach the roots. Do a whole strip before resting.', 'outdoors', 'productivity', 30, 'easy', 'outdoors', 'high', 'free', 'alone', 10, false, false, 'Keep your feet well clear of the tines.', null, 'published', 'seed', now()),
  ('outdoors-productivity-lawn-feed-by-the-stride', 'Lawn feed by the stride', 'Pace out the lawn to work out its area, weigh the right amount of feed, and scatter it in even strides across the grass. Water it in if no rain is due.', 'outdoors', 'productivity', 20, 'medium', 'outdoors', 'medium', 'paid', 'either', 20, false, false, 'Keep pets off the grass until the feed has washed in.', null, 'published', 'seed', now()),
  ('outdoors-productivity-moss-strip-on-the-path', 'Moss strip on the path', 'Kneel with a stiff brush and a scraper and clear every patch of moss from the garden path so it stops being slippery.', 'outdoors', 'productivity', 30, 'easy', 'outdoors', 'high', 'free', 'alone', 10, false, false, 'Wear knee pads or kneel on a folded sack.', null, 'published', 'seed', now()),
  ('outdoors-productivity-rose-deadhead-round', 'Rose deadhead round', 'Snip every faded rose back to the first strong leaf so the bush keeps flowering. Drop the heads in a bucket as you go.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, 'Wear gloves for the thorns.', null, 'published', 'seed', now()),
  ('outdoors-productivity-divide-a-crowded-perennial', 'Divide a crowded perennial', 'Lift a clump of overcrowded hardy geraniums or daylilies, split it with two forks back to back and replant the pieces around the border.', 'outdoors', 'productivity', 40, 'medium', 'outdoors', 'high', 'free', 'either', 20, false, false, null, 'how to divide perennials with two forks', 'published', 'seed', now()),
  ('outdoors-productivity-hedge-base-weed', 'Hedge base weed', 'Crawl along the base of the hedge pulling out the grass and nettles that have crept in, then lay a mulch to stop them coming back.', 'outdoors', 'productivity', 30, 'easy', 'outdoors', 'medium', 'free', 'alone', 10, false, false, 'Gloves and long sleeves for the nettles.', null, 'published', 'seed', now()),
  ('outdoors-productivity-cut-back-the-ornamental-grasses', 'Cut back the ornamental grasses', 'Grab a fistful of last year''s grass stems and cut them down to a hand''s height before the new shoots appear. Bundle the stems for the compost.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-stake-the-peonies', 'Stake the peonies', 'Put hoop supports around peonies before the buds get heavy, so the first heavy shower does not flatten them.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-clematis-tie-in-round', 'Clematis tie-in round', 'Tie the loose stems of a climbing clematis onto its trellis in a fan shape with soft twine, before they tangle into a knot.', 'outdoors', 'productivity', 15, 'medium', 'outdoors', 'low', 'free', 'alone', 20, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-wisteria-summer-cut', 'Wisteria summer cut', 'Shorten all the long whippy wisteria shoots to about five leaves from the main stems, so next year''s flowers have room.', 'outdoors', 'productivity', 30, 'medium', 'outdoors', 'medium', 'free', 'either', 20, false, false, 'Use a stable step ladder with someone holding it.', 'how to prune wisteria in summer', 'published', 'seed', now()),
  ('outdoors-productivity-lift-and-store-dahlias', 'Lift and store dahlias', 'After the first frost, cut dahlia stems down, lift the tubers, brush off the soil and leave them upside down in the shed to dry before storing.', 'outdoors', 'productivity', 30, 'medium', 'outdoors', 'medium', 'free', 'alone', 20, false, false, null, 'how to lift and store dahlia tubers', 'published', 'seed', now()),
  ('outdoors-productivity-tulip-bulb-lift', 'Tulip bulb lift', 'Dig up tulip bulbs once the leaves yellow, clean them and lay them in a tray to dry so you can plant them again in autumn.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-pot-up-the-self-seeders', 'Pot up the self-seeders', 'Gently lift the self-sown seedlings that have popped up in paths and gravel, pot them up and give them away or move them to gaps.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-lavender-hedge-trim', 'Lavender hedge trim', 'Trim a lavender hedge into a soft mound just after flowering, staying above the woody base. Hang the cuttings in the shed to dry for bags.', 'outdoors', 'productivity', 25, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-border-edging-with-a-half-moon', 'Border edging with a half-moon', 'Cut a crisp edge along the lawn''s border with a half-moon tool and a plank as a guide. The whole garden looks finished in half an hour.', 'outdoors', 'productivity', 30, 'medium', 'outdoors', 'high', 'free', 'alone', 20, false, false, null, 'how to edge a lawn with a half moon edger', 'published', 'seed', now()),
  ('outdoors-productivity-wildflower-meadow-mow', 'Wildflower meadow mow', 'In late summer, cut down your wildflower patch, leave the hay to drop its seeds for a few days, then rake it all off.', 'outdoors', 'productivity', 60, 'medium', 'outdoors', 'high', 'free', 'either', 20, false, false, 'Wear gloves and eye protection if using a strimmer.', null, 'published', 'seed', now()),
  ('outdoors-productivity-lawn-seed-for-bare-patches', 'Lawn seed for bare patches', 'Rough up each bare patch with a rake, sprinkle grass seed and a thin layer of compost and water it. Put sticks round it so nobody walks on it.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'medium', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-brush-the-leaves-off-the-lawn', 'Brush the leaves off the lawn', 'Use a besom or a broom to sweep leaves off the lawn into piles before they block the light. Bag them for leaf mould.', 'outdoors', 'productivity', 25, 'easy', 'outdoors', 'high', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-tree-tie-check', 'Tree tie check', 'Check every tree tie and stake in the garden. Loosen any that are cutting into the bark and replace the broken ones.', 'outdoors', 'productivity', 10, 'easy', 'outdoors', 'low', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-hydrangea-deadhead', 'Hydrangea deadhead', 'Snip old mophead flowers back to the first fat pair of buds in early spring. Leave them on through winter for frost cover.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'low', 'free', 'alone', 10, false, false, null, 'how to prune mophead hydrangeas', 'published', 'seed', now()),
  ('outdoors-productivity-climbing-rose-fan', 'Climbing rose fan', 'Untie a climbing rose, bend the long canes as near horizontal as you can and tie them back onto the wires. Sideways canes flower all along.', 'outdoors', 'productivity', 45, 'hard', 'outdoors', 'medium', 'free', 'either', 35, false, false, 'Thick gloves and long sleeves are a must.', null, 'published', 'seed', now()),
  ('outdoors-productivity-bulb-lasagne-pot', 'Bulb lasagne pot', 'Layer three kinds of bulbs in one big patio pot at different depths so they flower one after another from late winter to May.', 'outdoors', 'productivity', 25, 'easy', 'outdoors', 'low', 'paid', 'either', 10, false, false, null, 'how to plant a bulb lasagne pot', 'published', 'seed', now()),
  ('outdoors-productivity-ivy-off-the-fence', 'Ivy off the fence', 'Pull ivy runners off the fence panels before they force them apart, cutting the stems at the base and peeling upwards.', 'outdoors', 'productivity', 40, 'medium', 'outdoors', 'high', 'free', 'alone', 20, false, false, 'Wear gloves and eye protection for falling dust.', null, 'published', 'seed', now()),
  ('outdoors-productivity-bramble-clearance-hour', 'Bramble clearance hour', 'Cut back an invading bramble patch with loppers, then dig out the crowns with a mattock or spade so it does not regrow.', 'outdoors', 'productivity', 60, 'hard', 'outdoors', 'high', 'free', 'either', 35, false, false, 'Thick gloves, long sleeves and eye protection.', null, 'published', 'seed', now()),
  ('outdoors-productivity-pond-leaf-net', 'Pond leaf net', 'Stretch a net over the pond in autumn before leaves fall, and peg it down. Take it off and empty it once the trees are bare.', 'outdoors', 'productivity', 15, 'easy', 'outdoors', 'medium', 'paid', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('outdoors-productivity-pond-plant-thin-out', 'Pond plant thin-out', 'Pull out a third of the oxygenating weed from the pond, leaving it on the edge overnight so creatures can crawl back in.', 'outdoors', 'productivity', 20, 'easy', 'outdoors', 'medium', 'free', 'either', 10, false, false, 'Kneel on firm ground and never work by the pond alone with small children.', null, 'published', 'seed', now()),
  ('outdoors-productivity-water-lily-divide', 'Water lily divide', 'Lift an overgrown water lily basket, cut the rhizome into pieces with a growing tip and repot the best piece in fresh aquatic soil.', 'outdoors', 'productivity', 45, 'hard', 'outdoors', 'medium', 'paid', 'either', 35, false, false, 'Wear waterproof gloves and keep your footing at the water''s edge.', null, 'published', 'seed', now()),
  ('outdoors-productivity-clear-the-gravel-garden', 'Clear the gravel garden', 'Rake through the gravel, pulling every weed and leaf, then top up thin patches with a bag of new gravel.', 'outdoors', 'productivity', 30, 'easy', 'outdoors', 'medium', 'paid', 'alone', 10, false, false, null, null, 'published', 'seed', now()),
