  ('social-productivity-five-minute-tidy-dance-party', 'Five-minute tidy dance party', 'Put on one loud song with everyone at home and tidy the living room as fast as possible before it ends. Freeze like statues when the music stops.', 'social', 'productivity', 4, 'easy', 'indoors', 'high', 'free', 'with_friends', 15, true, false, null, null, 'published', 'seed', now()),
