  ('social-productivity-clean-the-communal-hallway-together', 'Clean the communal hallway together', 'Organise a twenty-minute session with the other flats to sweep, wipe the banister and clear the junk mail from the shared hallway.', 'social', 'productivity', 20, 'easy', 'indoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('social-productivity-shovel-the-street-path-with-neighbours', 'Shovel the street path with neighbours', 'After snow, team up with neighbours to clear the pavement along your row and make a path to the bus stop, starting with the older residents'' steps.', 'social', 'productivity', 45, 'medium', 'outdoors', 'high', 'free', 'with_friends', 20, false, false, 'Wrap up warm, bend your knees when lifting snow and spread grit on icy patches.', null, 'published', 'seed', now()),
  ('social-productivity-help-a-friend-paint-a-room', 'Help a friend paint a room', 'Turn up in old clothes and take charge of cutting in the edges while your friend rollers the walls. Bring a speaker and stop for one tea break only.', 'social', 'productivity', 240, 'medium', 'indoors', 'high', 'free', 'with_friends', 20, false, false, 'Ventilate the room, use a sturdy step ladder and keep paint away from eyes.', null, 'published', 'seed', now()),
  ('social-productivity-shared-twice-weekly-bodyweight-circuit-log', 'Shared twice-weekly bodyweight circuit log', 'Agree a short bodyweight circuit with a friend and do it together twice a week, logging sessions in a shared note so you both stay on track.', 'social', 'productivity', 30, 'medium', 'anywhere', 'high', 'free', 'with_friends', 20, false, false, 'Warm up first and stop if anything hurts.', null, 'published', 'seed', now()),
  ('social-productivity-community-garden-digging-day', 'Community garden digging day', 'Join a community garden''s work day and ask the coordinator for the heaviest job going, from turning compost to shifting woodchip. Learn everyone''s name.', 'social', 'productivity', 180, 'medium', 'outdoors', 'high', 'free', 'either', 20, false, false, 'Wear gloves and sturdy boots, lift with bent knees and drink plenty of water.', null, 'published', 'seed', now()),
  ('social-productivity-move-furniture-to-reset-a-shared-room', 'Move furniture to reset a shared room', 'With housemates, try a new layout for the living room in thirty minutes. Everyone gets one veto, and you must keep the result for a week.', 'social', 'productivity', 30, 'medium', 'indoors', 'high', 'free', 'with_friends', 20, false, false, 'Lift heavy furniture with two people and clear the floor first.', null, 'published', 'seed', now()),
  ('social-productivity-tideline-beach-clean-survey-with-friends', 'Tideline beach clean survey with friends', 'Take bags and gloves to the beach with friends and pick up rubbish along the tideline for an hour. Record what you find with a beach clean app for a survey.', 'social', 'productivity', 60, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Wear gloves, avoid touching sharp or unknown objects and check tide times.', null, 'published', 'seed', now()),
  ('social-productivity-run-errands-as-a-relay-with-a-partner', 'Run errands as a relay with a partner', 'Split the week''s errands with your partner by area: one takes the post office and bank, the other the shops. Race to meet at a café and compare times.', 'social', 'productivity', 60, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('social-productivity-group-hedge-trim-for-the-street', 'Group hedge trim for the street', 'Coordinate with neighbours to trim the hedges that overgrow the pavement on the same afternoon, sharing clippers and one green waste trip.', 'social', 'productivity', 90, 'medium', 'outdoors', 'high', 'free', 'with_friends', 20, false, false, 'Wear gloves and eye protection, and use a stable step instead of a chair.', null, 'published', 'seed', now()),
  ('social-productivity-cycle-the-parcels-with-a-friend', 'Cycle the parcels with a friend', 'Load up returns and donations in panniers and cycle the drop-off route with a friend instead of driving. Stop for a coffee halfway.', 'social', 'productivity', 60, 'medium', 'outdoors', 'high', 'free', 'with_friends', 20, false, false, 'Wear a helmet and bright clothing, and use cycle lanes where possible.', null, 'published', 'seed', now()),
  ('social-productivity-split-the-tin-fence-day', 'Split-the-tin fence day', 'Agree with your neighbour to paint both sides of the shared fence on the same Saturday, one tin bought by each household. Work from opposite ends and meet at the middle post.', 'social', 'productivity', 180, 'medium', 'outdoors', 'high', 'paid', 'with_friends', 20, false, false, 'Wear old clothes and gloves and keep paint off skin.', null, 'published', 'seed', now()),
  ('social-productivity-carry-a-neighbour-s-shopping-home', 'Carry a neighbour''s shopping home', 'Offer to meet an older neighbour at the shop and carry their bags home. Ask if they would like a regular day for it.', 'social', 'productivity', 30, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now()),
  ('social-productivity-garden-overhaul-for-a-friend-s-birthday', 'Garden overhaul for a friend''s birthday', 'Instead of a present, give a friend a morning of garden work with two other friends. Mow, weed and plant one pot as a finishing touch.', 'social', 'productivity', 180, 'medium', 'outdoors', 'high', 'paid', 'with_friends', 20, false, false, 'Wear gloves and use tools carefully, keeping children and pets away.', null, 'published', 'seed', now()),
  ('social-productivity-haul-a-donation-load-to-the-furniture-charity', 'Haul a donation load to the furniture charity', 'Book a furniture charity collection or deliver a chair or table with a friend. Wipe it down and photograph it first so they can list it fast.', 'social', 'productivity', 60, 'medium', 'anywhere', 'high', 'free', 'with_friends', 20, false, false, 'Lift heavy furniture in pairs and clear the route first.', null, 'published', 'seed', now()),
  ('social-productivity-window-pane-pointing-duel-with-a-flatmate', 'Window-pane pointing duel with a flatmate', 'One washes outside, one inside, so you can point at each other''s missed streaks through the glass. Finish every window in the flat.', 'social', 'productivity', 60, 'easy', 'anywhere', 'high', 'free', 'with_friends', 15, true, false, 'Only clean outside windows you can reach from the ground.', null, 'published', 'seed', now()),
  ('social-productivity-help-carry-chairs-after-a-community-event', 'Help carry chairs after a community event', 'At the end of a talk, gig or service, stay for fifteen minutes and help stack chairs and fold tables. Ask organisers if they need regular volunteers.', 'social', 'productivity', 15, 'easy', 'indoors', 'high', 'free', 'either', 10, false, false, null, null, 'published', 'seed', now()),
  ('social-productivity-scrub-the-playground-benches-with-parents', 'Scrub the playground benches with parents', 'Bring sponges and soapy water to the local playground with a few other parents and clean the benches and the climbing frame handles.', 'social', 'productivity', 45, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Use mild soap only and keep children out of the way of wet steps.', null, 'published', 'seed', now()),
  ('social-productivity-pick-fruit-to-share-with-the-street', 'Pick fruit to share with the street', 'When a tree is loaded with apples or plums, pick a big batch with a friend, bag it and leave free bags on neighbours'' doorsteps with a note.', 'social', 'productivity', 60, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Use a stable stepladder with someone holding it and wash the fruit.', null, 'published', 'seed', now()),
  ('social-productivity-team-bike-service-night', 'Team bike service night', 'Bring your bikes to one garage with friends and check tyres, oil chains and adjust brakes together, following one tutorial on a phone propped on the wall.', 'social', 'productivity', 90, 'medium', 'indoors', 'medium', 'free', 'with_friends', 20, false, false, null, 'basic bike maintenance for beginners', 'published', 'seed', now()),
  ('social-productivity-car-share-ferry-to-the-recycling-centre', 'Car-share ferry to the recycling centre', 'Offer neighbours space in your car for their bulky recycling and do one big trip together. Load heavy things last so they come out first.', 'social', 'productivity', 60, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, 'Lift in pairs and follow the recycling centre staff''s directions.', null, 'published', 'seed', now()),
  ('social-productivity-group-decorating-day-at-a-club-hall', 'Group decorating day at a club hall', 'Volunteer with others to repaint or tidy your sports club, scout hall or community centre. Ask for the task list in advance so you can bring the right kit.', 'social', 'productivity', 300, 'medium', 'indoors', 'high', 'free', 'with_friends', 20, false, false, 'Use ladders only with someone holding the base and ventilate painted rooms.', null, 'published', 'seed', now()),
  ('social-productivity-mow-the-lawn-for-a-neighbour-who-is-away', 'Mow the lawn for a neighbour who is away', 'When a neighbour goes on holiday, mow their front lawn and water their pots so the house looks lived in. Send them one photo of the tidy garden.', 'social', 'productivity', 45, 'easy', 'outdoors', 'high', 'free', 'either', 10, false, false, 'Wear closed shoes and keep children away from the mower.', null, 'published', 'seed', now()),
  ('social-productivity-box-duty-on-a-friend-s-moving-in-day', 'Box duty on a friend''s moving-in day', 'Spend a morning just on box duty for a friend moving in: you ferry from van to room by the label, and they unpack.', 'social', 'productivity', 120, 'easy', 'anywhere', 'high', 'free', 'with_friends', 10, false, false, 'Bend your knees when lifting and share heavy boxes.', null, 'published', 'seed', now()),
