  ('social-productivity-clear-a-path-for-a-wheelchair-user', 'Clear a path for a wheelchair user', 'Ask a neighbour who uses a wheelchair or walker if any bins, branches or clutter block their route, then clear them with a friend.', 'social', 'productivity', 30, 'easy', 'outdoors', 'high', 'free', 'with_friends', 10, false, false, null, null, 'published', 'seed', now())
